const DAY = 24 * 3600 * 1000;
const T0 = Date.UTC(2024, 0, 1);

function getAxisModel(chart: EChartsType, mainType: 'xAxis' | 'yAxis'): CartesianAxisModel {
    return getECModel(chart).getComponent(mainType, 0) as CartesianAxisModel;
}

function getTickValues(chart: EChartsType, mainType: 'xAxis' | 'yAxis'): number[] {
    const axisModel = getAxisModel(chart, mainType);
    return createAxisTicks(
        axisModel.axis,
        axisModel.getModel('axisTick') as unknown as AxisBaseModel
    ).ticks;
}

describe('axis_customValues', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should make ticks and labels at the customValues on time axis', function () {
        chart.setOption({
            xAxis: {
                type: 'time',
                min: T0,
                max: T0 + 10 * DAY,
                axisLabel: {
                    // The last one is out of the axis extent and should be ignored.
                    customValues: [T0 + 2 * DAY, T0 + 5 * DAY, T0 + 20 * DAY]
                },
                axisTick: {
                    customValues: [T0 + 2 * DAY, T0 + 5 * DAY, T0 + 20 * DAY]
                }
            },
            yAxis: {},
            series: [{
                type: 'line',
                data: [[T0 + DAY, 11], [T0 + 8 * DAY, 22]]
            }]
        } as EChartsOption);

        const axis = getAxisModel(chart, 'xAxis').axis;

        expect(getTickValues(chart, 'xAxis')).toEqual([T0 + 2 * DAY, T0 + 5 * DAY]);
        expect(axis.getTicksCoords().map(item => item.tickValue))
            .toEqual([T0 + 2 * DAY, T0 + 5 * DAY]);

        const labels = axis.getViewLabels();
        expect(labels.map(item => item.tickValue)).toEqual([T0 + 2 * DAY, T0 + 5 * DAY]);
        // Labels go through the normal (time) label formatter.
        expect(labels[0].formattedLabel).not.toEqual(labels[1].formattedLabel);
        expect(labels[0].formattedLabel.length).toBeGreaterThan(0);
        expect(labels[0].rawLabel.indexOf('2024-01-03')).toBe(0);
        expect(labels[1].rawLabel.indexOf('2024-01-06')).toBe(0);
    });

    it('should support the label formatter with customValues', function () {
        chart.setOption({
            xAxis: {
                type: 'time',
                min: T0,
                max: T0 + 10 * DAY,
                axisLabel: {
                    customValues: [T0 + 2 * DAY],
                    formatter: '{yyyy}/{MM}/{dd}'
                }
            },
            yAxis: {},
            series: [{ type: 'line', data: [[T0 + DAY, 11]] }]
        } as EChartsOption);

        const labels = getAxisModel(chart, 'xAxis').axis.getViewLabels();
        expect(labels.length).toBe(1);
        expect(labels[0].formattedLabel).toBe('2024/01/03');
    });

    it('should map customValues through the scale on category axis', function () {
        chart.setOption({
            xAxis: {
                type: 'category',
                data: ['A', 'B', 'C', 'D', 'E'],
                axisLabel: {
                    customValues: ['B', 'D', 'Z']
                },
                axisTick: {
                    customValues: ['B', 'D', 'Z']
                }
            },
            yAxis: {},
            series: [{ type: 'bar', data: [1, 2, 3, 4, 5] }]
        } as EChartsOption);

        expect(getTickValues(chart, 'xAxis')).toEqual([1, 3]);

        const labels = getAxisModel(chart, 'xAxis').axis.getViewLabels();
        expect(labels.map(item => item.tickValue)).toEqual([1, 3]);
        expect(labels.map(item => item.rawLabel)).toEqual(['B', 'D']);
        expect(labels.map(item => item.formattedLabel)).toEqual(['B', 'D']);
    });

    it('should keep the automatic behavior when customValues is absent', function () {
        chart.setOption({
            xAxis: {
                type: 'value',
                min: 0,
                max: 100
            },
            yAxis: {},
            series: [{ type: 'line', data: [[0, 1], [100, 2]] }]
        } as EChartsOption);

        const axis = getAxisModel(chart, 'xAxis').axis;
        const scaleTickValues = axis.scale.getTicks().map(tick => tick.value);

        expect(scaleTickValues.length).toBeGreaterThan(2);
        expect(getTickValues(chart, 'xAxis')).toEqual(scaleTickValues);
        expect(axis.getViewLabels().map(item => item.tickValue)).toEqual(scaleTickValues);
    });

});

